do $$declare x jsonb;f uuid;e uuid;e2 uuid;p jsonb;pending jsonb;applied jsonb;r uuid:=gen_random_uuid();before text;stock numeric;source numeric;c integer;w numeric;reason text;other jsonb;cause uuid:=gen_random_uuid();obs uuid:=gen_random_uuid();begin
 select t.x into x from correction_test.context t;f:=(x->>'factory')::uuid;e:=(x->>'entry')::uuid;e2:=(x->>'other_entry')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 p:=correction_test.payload(x,e,9,.5,2);before:=correction_test.operational();
 pending:=public.production_correction_command(f,'submit',p,r);
 perform correction_test.ok(pending->>'status'='PENDING','technician creates pending request');
 perform correction_test.ok(correction_test.operational()=before,'pending has zero operational effects');
 perform correction_test.ok((select effective_good=10 and good_quantity=10 and effective_scrap_kg=.25 from public.production_entries where id=e),'official and historical values preserved while pending');
 perform correction_test.ok(public.production_correction_command(f,'submit',p,r)=pending,'same UUID returns same pending receipt');
 perform correction_test.fails(format('select public.production_correction_command(%L,''submit'',%L,%L)',f,p||'{"reason":"Changed intent"}',r),'request_conflict');
 perform correction_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',f,jsonb_build_object('id',pending->>'id'),gen_random_uuid()),'42501');
 perform correction_test.fails(format('select public.correct_lean_production(%L,%L,%L)',f,p-array['expected_revision','allocations'],gen_random_uuid()),'42501');
 perform correction_test.ok(correction_test.operational()=before,'legacy and new unauthorized approvals do not post');
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 perform correction_test.ok(private.has_permission(f,'orders','approve') and not private.has_permission(f,'orders','edit'),'package-only engineer does not require broad Orders edit');
 select on_hand into stock from public.finished_goods_balances where factory_id=f and product_id=(x->>'product')::uuid and unit='meter';
 applied:=public.production_correction_command(f,'approve',jsonb_build_object('id',pending->>'id'),gen_random_uuid());
 perform correction_test.ok(applied->>'status'='APPROVED' and applied->>'requested_by'=x->>'worker' and applied->>'reviewed_by'=x->>'engineer','engineer approves employee proposal; separate actors retained');
 perform correction_test.ok((select effective_good=9 and good_quantity=10 and effective_scrap_kg=.5 and original_scrap_kg=.25 from public.production_entries where id=e),'approved exact effective Good and KG, immutable originals');
 perform correction_test.ok((select on_hand=stock-1 from public.finished_goods_balances where factory_id=f and product_id=(x->>'product')::uuid and unit='meter'),'Good decrement posted once');
 before:=correction_test.operational();
 perform correction_test.ok(public.production_correction_command(f,'approve',jsonb_build_object('id',pending->>'id'),gen_random_uuid())=applied,'another approval retry returns original approver receipt');
 perform correction_test.ok(correction_test.operational()=before,'repeat approval has no second Good/Scrap/WIP movement');
 perform correction_test.fails(format('update private.production_correction_requests set proposed=proposed||''{"good":"90"}'' where id=%L',pending->>'id'),'23514');
 perform correction_test.fails(format('update public.production_entry_corrections set reason=''Altered audit'' where id=%L',applied->>'correction_id'),'23514');
 perform correction_test.fails(format('delete from private.production_correction_requests where id=%L',pending->>'id'),'23514');
 p:=correction_test.payload(x,e,9.1234567890123456789,.1234567890123456789,3)||jsonb_build_object('reason','Measurement error — checked coil; خطأ في القياس');
 select on_hand into stock from public.finished_goods_balances where factory_id=f and product_id=(x->>'product')::uuid and unit='meter';
 select quantity_available into w from public.unfinished_lots where source_entry_id=e and quality_rejection_id is null;
 r:=gen_random_uuid();applied:=public.production_correction_command(f,'submit',p,r);
 perform correction_test.ok(applied->>'status'='APPROVED' and applied->>'requested_by'=applied->>'reviewed_by','authorized engineer automatically approves own correction');
 perform correction_test.ok((select effective_good=9.1234567890123456789 and effective_scrap_kg=.1234567890123456789 from public.production_entries where id=e),'precision preserved in approved Good and Scrap KG');
 perform correction_test.ok((select on_hand=stock+.1234567890123456789 from public.finished_goods_balances where factory_id=f and product_id=(x->>'product')::uuid and unit='meter'),'positive Good credit exactly once');
 perform correction_test.ok((select quantity_available=w+1 from public.unfinished_lots where source_entry_id=e and quality_rejection_id is null),'approved WIP delta uses existing lot');
 before:=correction_test.operational();perform public.production_correction_command(f,'submit',p,r);
 perform correction_test.ok(before=correction_test.operational(),'approved same UUID replay is immutable and idempotent');
 perform correction_test.ok(applied#>>'{proposed,reason}'=p->>'reason','edited suggestion and bilingual custom explanation stored verbatim');
 foreach reason in array array['','  ','x','  x  '] loop
  perform correction_test.fails(format('select public.production_correction_command(%L,''submit'',%L,%L)',f,p||jsonb_build_object('reason',reason),gen_random_uuid()),'22023');
 end loop;
 p:=correction_test.payload(x,e2,5,.35,0)||jsonb_build_object('reason','Custom explanation without choosing Other');
 applied:=public.production_correction_command(f,'submit',p,gen_random_uuid());
 perform correction_test.ok(applied->>'status'='APPROVED' and applied#>>'{proposed,reason}'=p->>'reason','arbitrary free text accepted');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform public.lean_command(f,gen_random_uuid(),'cause',jsonb_build_object('id',cause,'name','Local correction observation','name_ar','ملاحظة التصحيح'));
 perform public.lean_command(f,gen_random_uuid(),'scrap_observation',jsonb_build_object('id',obs,'entry_id',e2,'occurred_at',clock_timestamp(),'preliminary_cause_id',cause,'observation','Correction remains separate from cause review','response','Review separately'));
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 perform public.production_correction_command(f,'submit',correction_test.payload(x,e2,5,.4,0),gen_random_uuid());
 perform correction_test.ok((select reviewed_at is null and approved_cause_id is null from public.lean_scrap_events where id=obs),'correction approval does not approve a Scrap observation');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 p:=correction_test.payload(x,e2,4,.35,0);pending:=public.production_correction_command(f,'submit',p,gen_random_uuid());
 before:=correction_test.operational();
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 applied:=public.production_correction_command(f,'reject',jsonb_build_object('id',pending->>'id','reason','Re-measure before changing the official quantity'),gen_random_uuid());
 perform correction_test.ok(applied->>'status'='REJECTED' and applied->>'rejection_reason'='Re-measure before changing the official quantity','rejected request and explanation retained');
 perform correction_test.ok(correction_test.operational()=before,'rejection changes no inventory, WIP, reporting or historical evidence');
 perform correction_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',f,jsonb_build_object('id',pending->>'id'),gen_random_uuid()),'40001');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 pending:=public.production_correction_command(f,'submit',correction_test.payload(x,e2,4,.35,0),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 perform public.production_correction_command(f,'submit',correction_test.payload(x,e2,5,.4,0),gen_random_uuid());
 before:=correction_test.operational();
 perform correction_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',f,jsonb_build_object('id',pending->>'id'),gen_random_uuid()),'40001');
 perform correction_test.ok(correction_test.operational()=before and (select status='PENDING' from private.production_correction_requests where id=(pending->>'id')::uuid),'stale proposal remains pending; no overwrite of newer correction');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 p:=correction_test.payload(x,e2,4,.4,0)||jsonb_build_object('allocations',jsonb_build_array(jsonb_build_object('source_id',gen_random_uuid(),'quantity','1')));
 pending:=public.production_correction_command(f,'submit',p,gen_random_uuid());before:=correction_test.operational();
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 perform correction_test.fails(format('select public.production_correction_command(%L,''approve'',%L,%L)',f,jsonb_build_object('id',pending->>'id'),gen_random_uuid()),'source_unavailable');
 perform correction_test.ok(correction_test.operational()=before and (select status='PENDING' from private.production_correction_requests where id=(pending->>'id')::uuid),'source allocation failure rolls back posting and approval');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 perform set_config('TimeZone','UTC',true);
 pending:=public.production_correction_command(f,'submit',correction_test.payload(x,e2,5,.4,0),gen_random_uuid());
 perform set_config('TimeZone','Asia/Riyadh',true);
 perform set_config('request.jwt.claim.sub',x->>'engineer',false);
 applied:=public.production_correction_command(f,'approve',jsonb_build_object('id',pending->>'id'),gen_random_uuid());
 perform correction_test.ok(applied->>'status'='APPROVED','different session timezones do not create a false stale baseline');
 perform set_config('TimeZone','UTC',true);
 perform correction_test.ok((select bool_and(on_hand>=reserved and on_hand>=0) from public.finished_goods_balances where factory_id=f),'stock and commitments conserved');
 perform correction_test.ok(not exists(select 1 from private.production_recording_v3_activation where factory_id=f and enabled),'late recording remains disabled');
end$$;
select count(*) as policy_assertions from correction_test.checks;
